 }
 function frame(now){const dt=Math.min(.032,(now-last)/1000);last=now;drawBackground();if(started&&!ended){time-=dt;if(time<=0){ended=true;finish(player.health>=enemy.health?'YU WINS':'KAITO WINS')}}player.update(dt);enemy.update(dt);if(started&&!ended&&(player.health<=0||enemy.health<=0)){ended=true;finish(player.health<=0?'KAITO WINS':'YU WINS')}updateBars();player.draw();enemy.draw();document.getElementById('timer').textContent=Math.max(0,Math.ceil(time));requestAnimationFrame(frame)}
 function finish(text){const r=document.getElementById('roundText');r.textContent=text;r.style.opacity=1;setTimeout(()=>{started=false;document.getElementById('startBtn').textContent='PLAY AGAIN';document.getElementById('start').classList.remove('hidden')},1300)}
 function reset(){player.x=W*.27;enemy.x=W*.73;player.health=enemy.health=100;time=60;ended=false;player.vx=enemy.vx=0}
-document.getElementBy('startBtn');
 const startBtn=document.getElementById('startBtn');startBtn.addEventListener('click',()=>{reset();document.getElementById('start').classList.add('hidden');started=true;const r=document.getElementById('roundText');r.textContent='FIGHT!';r.style.opacity=1;setTimeout(()=>r.style.opacity=0,700)});
 requestAnimationFrame(frame);
 </script>
 </body>
